          .map((e) => (e as YamlMap)['os'] as String)
          .toSet();
      expect(
        targets,
        {'linux', 'windows'},
        reason:
            '#1265 broke exactly these two — the smoke must cover '
            'both, on the same hosted runners the nightly uses',
