/// Dart structures so two job step-lists can be deep-compared.
Object? plain(Object? node) {
  if (node is YamlMap) {
    return {
      for (final e in node.entries) plain(e.key): plain(e.value),
    };
  }
  if (node is YamlList) {
    return [for (final e in node) plain(e)];
  }
  return node;
}

