// gh-1477 — the `Derive version` job in build-mobile.yml ran
// actions/checkout with `fetch-depth: 0` (full history + every tag + every
// blob ever written) under `timeout-minutes: 10`. The repo gains a release
// tag + commits daily, so the full fetch only got slower until, on
// 2026-10-10, it outgrew the ceiling: the job was killed exactly 600s in,
// mid-`git fetch`, and the whole TestFlight leg of the daily train
// collapsed to `cancelled` (run 38027695551, issue #1472). A time bomb,
// not a flake — and the twin `Derive version` job in build-macos.yml, the
// daily-publish `plan` job, and a family of ci.yml guard jobs carried the
// same shape.
//
// Deliberately text/YAML-level asserts (the issue's "workflow-shape test"
// never-again, same static-assert pattern as
// nightly_desktop_leg_guard_test.dart / store_automation_guard_test.dart):
//  AC1  every checkout step that asks for full history
//       (`fetch-depth: 0`) must pair it with `filter: blob:none` — the
//       jobs read tags / commit metadata / `git log` ranges, never
//       historical file contents, and a blobless clone skips transferring
//       every blob ever written while git still lazy-fetches the rare
//       blob something actually asks for,
//  AC2  the metadata-only daily-train jobs (derive version ×2, daily
//       plan) whose ONLY pre-timeout work is that fetch must carry a ≥20m
//       ceiling — the 10m seatbelt was the bomb's detonator.
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();

/// Every checkout step (`uses: actions/checkout…`) across all workflow
/// jobs, as (workflow, jobId, stepIndex, step).
Iterable<(String, String, int, YamlMap)> checkoutSteps(String workflowPath) {
  final jobs = loadYaml(read(workflowPath))['jobs'] as YamlMap;
  final out = <(String, String, int, YamlMap)>[];
  for (final entry in jobs.entries) {
    final steps = (entry.value as YamlMap)['steps'];
    if (steps is! YamlList) continue;
    for (var i = 0; i < steps.length; i++) {
      final step = steps[i];
      if (step is! YamlMap) continue;
      final uses = step['uses']?.toString() ?? '';
      if (uses.startsWith('actions/checkout@')) {
        out.add((workflowPath, entry.key as String, i, step));
      }
    }
  }
  return out;
}

bool asksFullHistory(YamlMap step) {
  final depth = (step['with'] as YamlMap?)?['fetch-depth'];
  return depth == 0 || depth == '0';
}

void main() {
  final workflows = Directory('.github/workflows')
      .listSync()
      .whereType<File>()
      .where((f) => f.path.endsWith('.yml'))
      .map((f) => f.path)
      .toList()
    ..sort();

  group('AC1 — full-history checkouts are blobless (gh-1477)', () {
    for (final workflow in workflows) {
      test(workflow, () {
        for (final (path, jobId, stepIndex, step)
            in checkoutSteps(workflow)) {
          if (!asksFullHistory(step)) continue;
          final filter = (step['with'] as YamlMap?)?['filter'];
          expect(
            filter,
            'blob:none',
            reason:
                '$path job "$jobId" step $stepIndex pairs `fetch-depth: 0` '
                'with NO `filter: blob:none` — a full clone transfers every '
                'blob ever written and grows daily (gh-1477: the fetch '
                'outgrew its own 10m job timeout and cancelled the daily '
                'TestFlight leg, run 38027695551). The job reads tags / '
                'commit metadata only; blobs are waste.',
          );
        }
      });
    }
  });

  group('AC2 — metadata-only daily-train jobs carry a ≥20m seatbelt', () {
    const metadataOnlyJobs = <String, List<String>>{
      // (workflow, jobId) — the job's only pre-timeout work is a tags/
      // metadata fetch; a cancelled job collapses the whole daily train.
      '.github/workflows/build-mobile.yml': ['version'],
      '.github/workflows/build-macos.yml': ['version'],
      '.github/workflows/daily-publish.yml': ['plan'],
    };
    for (final entry in metadataOnlyJobs.entries) {
      for (final jobId in entry.value) {
        test('${entry.key} job "$jobId"', () {
          final job =
              (loadYaml(read(entry.key))['jobs'] as YamlMap)[jobId]
                  as YamlMap;
          final timeout = job['timeout-minutes'];
          expect(
            timeout,
            isNotNull,
            reason:
                '${entry.key} job "$jobId" lost its explicit ceiling — the '
                '#351 watch-budget arithmetic needs one',
          );
          expect(
            (timeout as num) >= 20,
            isTrue,
            reason:
                '${entry.key} job "$jobId" runs a full-history fetch under '
                'only ${timeout}m — the exact gh-1477 bomb (fetch outgrew '
                'the ceiling → job cancelled → daily leg collapsed). '
                '≥20m is the seatbelt; the blobless filter (AC1) makes the '
                'fetch itself cheap.',
          );
        });
      }
    }
  });
}

{"content":"// gh-1659 — the Office add-in acceptance suite folds into the shared
// ci.yml matrix. The suite lived in office-addin.yml under push/
// pull_request triggers, so every lib/**- or flutter_app/**-touching PR
// paid for a SECOND standalone workflow whose check had to be tracked
// separately in branch protection. Now:
//  AC1  a lib/**-only PR runs the office-addin suite INSIDE ci.yml (one
//       workflow entry per push), path-gated on a new `office_addin`
//       changes output carrying the exact path list the standalone
//       triggers used,
//  AC2  office-addin.yml keeps ONLY workflow_dispatch (the daily-publish
//       addin leg still dispatches it — its #423 dispatch group stays
//       intact); the push/pull_request blocks are gone so a PR never
//       spawns the separate workflow again,
//  AC3  the check name stays coherent for the ruleset: the moved job
//       keeps the bare check-run name "Office add-in suite" (only the
//       workflow display prefix changes to "CI / …"),
//  AC4  no path-skip regression: out-of-scope PRs skip the leg exactly as
//       today, and a red suite reddens the required Quality gate
//       (platform class, #1368) while skipped reporting stays correct.
//
// Deliberately YAML-level asserts (the ci_binaries_arch_gate_test.dart /
// ci_1267_path_triggered_legs_test.dart static pattern): they pin the
// wiring — the suite itself is exercised by CI, not locally (no local
// tests run GitHub runners). The job body exists in TWO files on purpose
// (ci.yml = the PR gate, office-addin.yml = the dispatch-only daily leg);
// the step-parity test below is the drift guard that keeps both copies
// running the same suite.
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();
YamlMap jobsOf(String workflowPath) =>
    loadYaml(read(workflowPath))['jobs'] as YamlMap;

const ci = '.github/workflows/ci.yml';
const addin = '.github/workflows/office-addin.yml';
const legId = 'office-addin-suite';

/// The exact path list the retired standalone office-addin.yml push/PR
/// triggers carried (C1: "same path list as today").
final officeAddinGrep = r"grep -qE '(^office_addin/|^flutter_app/|^packages/^|"
    r"^lib/|^pubspec\.lock$|^scripts/build_office_addin\.sh$"
    r"|^\.github/workflows/office-addin\.yml$)'";

/// Recursively convert the yaml package's unmodifiable views into plain
/// Dart structures so two job step-lists can be deep-compared.
Object? plain(Object? node) {
  if (node is YamlMap) {
    return {
      for (final e in node.entries) plain(e.key): plain(e.value),
    };
  }
  if (node is YamlList) {
    return [for (final e in node) plain(e)];
  }
  return node;
}

void main() {
  final ciBody = read(ci);
  final ciJobs = jobsOf(ci);
  final addinBody = read(addin);
  final addinJobs = jobsOf(addin);

  group('AC2 — office-addin.yml is dispatch-only', () {
    final on = loadYaml(addinBody)['on'] as YamlMap;

    test('workflow_dispatch stays; push and pull_request are gone', () {
      expect(
        on.containsKey('workflow_dispatch'),
        isTrue,
        reason:
            'daily-publish.yml dispatches this workflow for the addin leg '
            '(issues #343/#344 watcher) — the entry must survive',
      );
      expect(
        on.containsKey('push'),
        isFalse,
        reason:
            'gh-1659 AC2: a push must never spawn the standalone Office '
            'add-in workflow again — the gate lives in ci.yml now',
      );
      expect(
        on.containsKey('pull_request'),
        isFalse,
        reason:
            'gh-1659 AC2: a PR must never spawn the standalone Office '
            'add-in workflow again (two CI entries per push today)',
      );
    });

    test('the #423 dispatch-group concurrency block stays intact', () {
      final concurrency = loadYaml(addinBody)['concurrency'] as YamlMap;
      final group = concurrency['group'].toString();
      expect(
        group,
        contains("github.event_name == 'workflow_dispatch'"),
        reason:
            'issue #423: a workflow_dispatch run (the daily-publish addin '
            'leg) gets its OWN concurrency group so a push landing '
            'mid-daily cannot cancel it — the special-case must survive '
            'the trigger retirement',
      );
      expect(group, contains('dispatch-{0}'));
      expect(concurrency['cancel-in-progress'], isTrue);
    });

    test('the daily leg still has a real job to dispatch and watch', () {
      final job = addinJobs[legId] as YamlMap?;
      expect(
        job,
        isNotNull,
        reason:
            'daily-publish.yml dispatch_and_watch.sh office-addin.yml '
            'waits on this job — an empty workflow would break the daily '
            'train (test matrix: "the daily dispatch leg still works")',
